import { articleMapper } from '../../app/routes/article/article.mapper';

describe('article.mapper - readingTime calculation', () => {

  // Test 1: Verify readingTime field is present in mapped article
  it('should include readingTime field in mapped article response', () => {
    const mockArticle = {
      slug: 'test-article',
      title: 'Test Article',
      description: 'Test description',
      body: 'This is a test article body with some words.',
      tagList: ['test'],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result).toHaveProperty('readingTime');
    expect(typeof result.readingTime).toBe('number');
  });

  // Test 2: Exactly 200 words should return 1 minute
  it('should calculate readingTime as 1 minute for exactly 200 words', () => {
    const words200 = Array(200).fill('word').join(' ');
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: words200,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1);
  });

  // Test 3: 450 words should return 3 minutes (Math.ceil(450/200))
  it('should calculate readingTime as 3 minutes for 450 words', () => {
    const words450 = Array(450).fill('word').join(' ');
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: words450,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(3); // Math.ceil(450/200) = 3
  });

  // Test 4: Short articles (< 200 words) should default to 1 minute
  it('should default readingTime to 1 minute for articles with less than 200 words', () => {
    const words50 = Array(50).fill('word').join(' ');
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: words50,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
