    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1);
  });

  // Test 5: Empty body should default to 1 minute
  it('should default readingTime to 1 minute for empty body', () => {
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: '',
