      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1);
  });

  // Test 6: Null body should default to 1 minute
  it('should handle null body gracefully and default to 1 minute', () => {
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: null,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1);
  });

  // Test 7: Undefined body should default to 1 minute
  it('should handle undefined body gracefully and default to 1 minute', () => {
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: undefined,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1);
  });

  // Test 8: Body with multiple spaces should count words correctly
  it('should count words correctly when body has multiple consecutive spaces', () => {
    const bodyWithSpaces = 'word1    word2     word3'; // 3 words with multiple spaces
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
      body: bodyWithSpaces,
      tagList: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      favorited: false,
      favoritesCount: 0,
      author: { username: 'testuser', bio: '', image: '', following: false }
    };

    const result = articleMapper(mockArticle, null);

    expect(result.readingTime).toBe(1); // 3 words < 200, so minimum 1
  });

  // Test 9: Body with newlines and tabs should count words correctly
  it('should count words correctly when body has newlines and tabs', () => {
    const bodyWithWhitespace = 'word1\n\nword2\t\tword3\nword4';
    const mockArticle = {
      slug: 'test-article',
      title: 'Test',
      description: 'Test',
