      title: 'New Test Article',
      description: 'Test description',
      body: Array(300).fill('word').join(' '), // 300 words
      tagList: ['test']
    };
    const mockUserId = 1;

    const result = await articleService.createArticle(newArticleData, mockUserId);

    expect(result).toHaveProperty('readingTime');
    expect(result.readingTime).toBe(2); // Math.ceil(300/200) = 2
