  // Test 15: updateArticle should recalculate readingTime after update
  it('should recalculate readingTime when article body is updated', async () => {
    const slug = 'existing-article';
    const updateData = {
      body: Array(600).fill('word').join(' ') // 600 words
    };
    const mockUserId = 1;

    const result = await articleService.updateArticle(slug, updateData, mockUserId);

    expect(result).toHaveProperty('readingTime');
    expect(result.readingTime).toBe(3); // Math.ceil(600/200) = 3
  });
